pub struct WithLogging<C> { inner: C }        // wrapper owns the component

impl<C: Component> Component for WithLogging<C> {
    fn render(&self, props: &Props) -> Markup {
        log::info!("render");                 // concern lives in the wrapper
        self.inner.render(props)              // wrapped component unaware
    }
}

